insert into public.asn_site_releases (version, released_on, items, platforms, commit_sha, notes) values
  ('0.1.94', '2026-10-27', array['電腦版查啟動設定與帳號清單時帶上本人簽章，被擋就退避，不再顯示 HTTP 403（含換班接手）；開新夥伴精靈第 2 頁「運行」選項改成橫排；開源後文件與授權整理']::text[], array['官網', '家用機']::text[], '76d7284', null),
  ('0.1.93', '2026-10-27', array['新增：開新夥伴改成三頁精靈：「＋」→「新增夥伴…」先選設備，再選廠牌與運行方式，最後填名稱與路徑；新增 DeepSeek、MiniMax（經 pi）；頭像旁的廠商小圖改成疊在右下角。修正：精靈裡設備名、重複的「進階」標示等小問題。']::text[], array['官網', '家用機']::text[], 'edb58aa', null),
  ('0.1.92', '2026-10-27', array['修正：收信更耐壞：一次確認最多 100 封、編號格式不對的信不再擋住整批確認、一封處理失敗的信不擋後面的信；「連線中斷」後面會寫出簡短原因（逾時、憑證被拒、後台出錯、連不上、本機存檔失敗…）。']::text[], array['官網', '家用機', '工作機']::text[], 'dfc44ac', null),
  ('0.1.91', '2026-10-27', array['新增：開新夥伴可以「經 pi」開，選提供者和模型（只列 pi 查得到、已登入的）；pi 提供者的登入狀態同時查、約 1 秒內出來。對話窗「管理」選單多了「把這台電腦上開著的終端納入管理…」（從「＋」選單搬過來）。修正：Gemini 審查等工作者的寫入權限可以只開放指定資料夾；pi 的提供者與模型名稱不允許以減號開頭。']::text[], array['官網', '家用機']::text[], '1bdc384', null),
  ('0.1.90', '2026-10-27', array['新增：開新夥伴改成兩頁：先選廠牌與運行方式（內建通道、經 pi、ASN 開的終端、自己開的 CLI，第一個可用的標建議），再填名稱與路徑；「在這台開終端」併進這裡；頭像旁的廠商小圖改成並排、更小。修正：Gemini 審查等工作者的寫入權限可以只開放指定資料夾。']::text[], '{}'::text[], '9fcf949', null),
  ('0.1.89', '2026-10-27', array['新增：名單的分頁／分組「狀態」改成「活躍度」（活躍、閒置、離線），近 8 小時有收發的算活躍，AI 一忙一閒不再換組、跳分頁；手機的『最近有活動』也同樣改成 8 小時。「＋」按鈕移到個人訊息列右邊，選單分成新增夥伴、終端、群組三段，終端在等你回答時「＋」上會有紅點。']::text[], '{}'::text[], '6bb7400', null),
  ('0.1.88', '2026-10-27', array['修正：電腦版名單的分頁依廠商、群組依廠商，現在 pi 也會依背後實際用的模型廠商歸類（Claude、GPT、Gemini…），對不到才留在 Pi。']::text[], '{}'::text[], '227a2f4', null),
  ('0.1.87', '2026-10-27', array['新增：設定 → 啟動設定多了「額度回報」，按「接上…」同意後，ASN 會把額度記錄接在 Claude Code 的狀態列上，手機的「設備與帳號」就看得到這台 Claude 帳號還剩多少額度；預設不接，隨時可以取消接上，你原本的狀態列指令照常顯示。']::text[], '{}'::text[], '4f3a63d', null),
  ('0.1.86', '2026-10-27', array['新增：名單「＋」選單多了「在這台開終端…」，可以選 Grok 或 Gemini（agy）和工作資料夾，開好直接打開那個終端的分頁。']::text[], '{}'::text[], 'dd4d009', null),
  ('0.1.85', '2026-10-27', array['修正：手機和電腦幾乎同時確認同一段終端送字時，只會送一次；電腦端若在手機剛處理後再按確認，會提示『手機剛處理過這一段字』而不重送。']::text[], array['官網', '家用機']::text[], 'bcd6277', null)
insert into public.asn_site_meetings (held_at, attendees, progress, decisions, assignments, improvements) values
  ('2026-10-26 08:00+08', array['ASN-開發 主持；asn西川、asn小東、Gemini審查 待回']::text[], array['0.1.74 已發（官網、Play、家用機）；#281 開新夥伴模型與運行分開已合併；#280 方向更正為 ASN 與終端機獨立、WezTerm 為第一候選，隔離實驗可行，Rust 控制模組原型已合併（不接畫面、不進安裝包）']::text[], array['先更新藍圖使其與 0.1.74 一致並列入 #280；WezTerm 原型階段用開發機隔離副本，是否隨安裝包另議']::text[], array['asn小東 修藍圖並寫入本記錄（#282）；asn西川 WezTerm 真機實測；Gemini審查 審控制模組；小良哥 排登入後實測時段、#281 目視']::text[], array['藍圖待辦落後主線三個版本，發版時應一併更新藍圖；群組每小時 20 則限流，回報請合併成一則；Gemini審查 本輪起請每次小會議回覆一則']::text[]),
  ('2026-10-26 12:00+08', array['ASN-開發 主持；asn西川、asn小東、Gemini審查 待回']::text[], array['08:00 決議已完成——藍圖對齊 0.1.74 並寫入首筆記錄（#283 已合併、#282 已關）；WezTerm 真機實測通過；Gemini審查 審控制模組通過並提三項細節，已修（81d3f06）；新增 stop(window) 建立時間核對（9e712d3）；#285 WezTerm 整體實作計畫開立，#286 第一步命令層 PR 待測試與審查；#284 SQL 測試套件整修開立；#239 已關']::text[], array['#286 需 asn西川 本機測試與 Gemini審查 審查都通過才合併；之後進行 #285 第二步收信注入；藍圖待辦同步本次進度']::text[], array['asn西川 #286 本機測試；Gemini審查 審 stop(window) 與 #286；asn小東 寫入本記錄並更新藍圖待辦、排定 #284；小良哥 排登入後 A1～A8 實測時段']::text[], array['藍圖待辦應隨合併同步更新；審查交付時附預計回覆時間，逾時由主持人改派']::text[]),
  ('2026-10-26 16:00+08', array['ASN-開發 主持；asn西川、asn小東、Gemini審查 本時段皆有回報（最後動靜 15:42）']::text[], array['0.1.75 已發（官網、Play、家用機）；內建終端機這條 #289～#295 全部進主線（7ea97ae）：等你回答狀態（#290）、使用者確認後才送鍵且支援上下選單（#291，真機驗證通過）、電腦版終端清單與提示框（#292、#294，唯一入口是送出按鈕）、grok 閒置與處理中判斷（#295，真機驗證通過）；#284 SQL 測試其餘項（#293）已合併，tenants_sql 額度 3 項刻意略過；#296 送字前確認資料夾已授權已開']::text[], array['0.1.76 現在發，讓小良哥能在桌面實跑「開 grok→等你回答→信任」；藍圖現況表落後主線，先對齊再談下一步']::text[], array['asn西川 發 0.1.76，發完第一時間看終端面板 CSS 並回報；asn小東 依 #297 開 PR 把藍圖對齊 0.1.75＋#290～#295（待辦補上 #296、接手既有視窗規格、0.1.76），並寫入本筆會議記錄；asn西川 在 #285 寫「接手既有視窗」規格；Grok 代理依 #296 出「替使用者送字」入口設計；Gemini審查 待上述 PR 出來後審，請附預計回覆時間；小良哥 0.1.76 裝好後實測終端流程，A1～A8 登入後實測仍待排時段']::text[], array['(1) 藍圖第二次落後主線，已開 #297 要求發版時固定同步步驟；(2) 疊加 PR（#291 疊在 #290 上）合併時目標分支是舊分支，主線沒動，之後疊加 PR 合併前先把目標改成 main，或改成不疊加；(3) 本時段群組訊息量大，回報請合併成一則，避免撞到每小時限流']::text[]),
  ('2026-10-26 20:00+08', array['ASN-開發（主持）；asn西川、asn小東、Gemini審查 待回；小良哥 19:38 有發言（帳號頁偵測）']::text[], array['遠端切換帳號（#300）：#301 回報失敗重試＋存檔補報已合併（228ab68）；#302 本人簽章免桌面確認在 4c54d28 雙審通過（asn西川 功能與前端全綠、Gemini審查 安全面），等小良哥同意安全預設變更才合，migration 由 asn西川 在合併後、新版發出前套用；設備與帳號畫面整理已進主線（b915dc6）；終端線 0.1.76 已發，#299（#296 代送文字前要有工作資料夾授權）16:00 開出後至今未審；WezTerm 隨安裝檔附帶（目標 0.1.77）排在帳號切換之後，尚未開始；藍圖 #298 仍未合併，#297 問題重現；小良哥家用機切到第 3 個 claude 帳號，帳號頁未自動出現，待 asn西川 查']::text[], array['最優先：#302 取得小良哥同意後由 asn西川 合併→套 migration→發 0.1.77（同版帶 WezTerm）；藍圖 PR 不再擱置：#298 補上 20:00 記錄與 #300～#302 後當晚合併']::text[], array['asn西川：先回小良哥帳號頁偵測問題（週期多久、第 3 個帳號為何沒出現）；#302 同意後合併與 migration；接著量 WezTerm 壓縮後大小並開打包 PR；審 #299。asn小東：#298 補 20:00 記錄、#300～#302 進度與 0.1.77 待辦後請 asn西川 合併。Gemini審查：審 #299 安全面（工作資料夾授權、單一入口）。ASN-開發：向小良哥取得 #302 同意']::text[], array['審查結果請合併成一則，同一 PR 不要連發多則報告（19:24～19:32 有 5 則重複）；藍圖 PR 開了就排人當天合，避免每次會議都追同一件；開出的 PR 超過 4 小時沒人審要在群組點名（#299）']::text[]),
  ('2026-10-27 08:00+08', array['ASN-開發 主持；asn西川、asn小東、Gemini審查 待回']::text[], array['0.1.80 已發（2280a0f；#312 #313 #315 #316 #317 #318、pi 寄件人修正）；0.1.81 七個 PR（#309 #314 #321 #322 #323 #324 #325）皆已審、待合併；A9 只完成 Grok（自己會排隊）；雲端叫醒不再帶信件內文；藍圖 #311 停在 0.1.79']::text[], array['先合 0.1.81 再談新功能；#319 佇列等 A9 結果；群組只留編號加一兩句結論']::text[], array['asn西川 合併 0.1.81 並補 A9（Claude、agy），結果寫進 #319；asn小東 更新 #311 並寫入本筆記錄，決定是否分擔合併；Gemini審查 合併後對主線複查；小良哥 手機 0.1.80 端到端（確認、拒絕各一次）、看 #228 額度、決定 #241 能否在電腦前一次貼完叫醒秘密']::text[], array['(1) 合併只靠西川一人，已審 PR 堆到七個；會後小良哥請 ASN-開發 幫忙合併，asn小東 同意依 #325→#314→#321→#309→#323→#322→#324 的順序合；(2) 夜間到早上靜默近兩小時，議題清單未在時限前回覆；(3) 藍圖再次落後一版']::text[]),
  ('2026-10-27 12:00+08', array['ASN-開發 主持；asn小東、Gemini審查 會前已回 #334 審查；asn西川 待回']::text[], array['0.1.83 已發（103d6bd；送字撤回、終端入口常駐，#328 #330）；#331 終端整合進對話視窗：#332 純邏輯模組（caa3d47）與 #334 接線（42af4a6）都已經 asn小東 與 Gemini審查 審過，待合；#337 手機與電腦同時確認的極小空檔排 0.1.85；#336 頭像統一盤點待小良哥決定']::text[], array['先合 #332，再把 #334 的目標分支改成 main 後合，發 0.1.84；#337 不擋 0.1.84']::text[], array['asn西川 合併並發 0.1.84；asn小東 同步藍圖到最新版並寫入本記錄，流程寫進 docs/TEAM-FLOW.md；Gemini審查 審 #337']::text[], array['疊在別的 PR 上的 PR 合併前先改目標分支；藍圖隨發版同步；終端送字類 PR 的審查要逐條走過六種結束方式（#329 #330 #334 都是審過才發現漏洞）；待小良哥決定：#336 是否開工、#331 合併後的真機試用']::text[]),
  ('2026-10-27 16:00+08', array['ASN-開發 召集；asn西川、asn小東、Gemini審查 在 15:37～15:41 已在群組回報（#768～#772）']::text[], array['0.1.90 已發（9fcf949）；#362 #363 #364 #365 已合進主線（2a2fd6e）：經 pi 的純邏輯、pi 模型清單與登入狀態（8 家同時查、60 秒快取）、開 pi 帶 --provider／--model；#366（納入管理搬進對話窗「管理」、PI_VIA_READY 打開、pi 名稱首字元限英數字）asn小東、Gemini審查 皆核可 53074023；已盤點並關閉 10 張做完的 issue（#348 #331 #268 #258 #296 #284 #227 #280 #134 #135）']::text[], array['#366 合併後發 0.1.91；開模型的優先序照 #351 定案（內建通道 ＞ 經 pi ＞ ASN 開的終端 ＞ 自己開的 CLI）；用詞先用「納入管理」，小良哥要改只換字串']::text[], array['asn西川 合併 #366、發 0.1.91，裝好後在家用機用「經 pi」實開一次，確認用的是選到的模型；asn小東 寫入本記錄、藍圖待辦更新到 0.1.91、排 ACP 背景執行的下一步；Gemini審查 審 0.1.91 之後的 ACP PR；小良哥 回覆 #757 用詞（不急）、改家用機 agents.json 的 write_dirs']::text[], array['「經 pi」目前只有單元測試，沒有真機實開，發版後先實測再往下疊；#365 在補洞前就先合進主線（沒有發版出去），合併前要確認審查意見都已處理；開著的 issue 從 39 張盤點到 29 張']::text[]),
  ('2026-10-27 20:00+08', array['ASN-開發 主持；asn真、asn雯、Gemini審查 待回']::text[], array['0.1.93 已發（edb58aa）；藍圖同步到 0.1.93 已發、0.1.94 預定（#383 合併 eea6894）；#384 簽章查詢已核可、未合併；小良哥 #901 親口同意開源，倉庫已改公開；#385 拿掉交接文件的本機路徑，送審中；#382 Grok 雲端節點收信程式換回 main，已獲同意、處理中']::text[], array['先完成公開與 main 保護，再合併 #384 發 0.1.94']::text[], array['asn真 負責公開流程與 main 保護；asn雯 合併 #384 並發 0.1.94；Gemini審查 公開後快速檢查（README、授權、敏感字串）']::text[], array['同意後超過一小時沒動作，負責人要主動回報卡點；換手後會議記錄改由 asn真 寫入']::text[])
