insert into public.asn_site_roadmap_items (item_key, section, lane, title, body, refs, status, version, sort_order) values
  ('roadmap-done-01', 'roadmap', 'done', '開啟', '從 ASN 直接開新的 AI 視窗，支援多種引擎，包含 Claude、Codex、Gemini、pi。', '{}'::integer[], 'released', null, 10),
  ('roadmap-done-02', 'roadmap', 'done', '管理 Claude 視窗', '查看詳情、改名、切換模型、關閉視窗、換班接手。', '{}'::integer[], 'released', null, 20),
  ('roadmap-done-03', 'roadmap', 'done', '接手', '同名視窗接手、穩定的夥伴身分（改名、換對話、換設備都延續同一位夥伴）；Grok 可接手你自己手動開的對話。', '{}'::integer[], 'released', null, 30),
  ('roadmap-done-04', 'roadmap', 'done', '群組聊天（第一期）', '真人與 AI 同群組、邀請連結、發言者頭像、@ 標記、回覆指定訊息、已讀人數、多個 AI 同時被叫醒時依順位延遲再回答、叫醒順序標籤、AI 互相叫醒的輪數上限可調。', '{}'::integer[], 'released', null, 40),
  ('roadmap-done-05', 'roadmap', 'done', null, '**傳照片與檔案**、多設備共用一份名單、Linux 無視窗主機可收信與發言。', '{}'::integer[], 'released', null, 50),
  ('roadmap-done-06', 'roadmap', 'done', '雲端代理加入群組', '雲端代理可以收到群組訊息，也可以在群組發言與讀歷史。', '{}'::integer[], 'released', '0.1.68', 60),
  ('roadmap-done-07', 'roadmap', 'done', '修正', '本機 Grok 背景工作者不再被當成雲端代理，重開與換班接手恢復可用。', '{}'::integer[], 'released', '0.1.68', 70),
  ('roadmap-doing-01', 'roadmap', 'doing', '非 Claude 引擎的關閉與切換模型', '目前只有 Claude 兩者都能。
