insert into public.asn_site_matrix_rows (row_key, name, kind, note, sort_order) values
  ('claude', 'Claude', '互動視窗', '要在電腦端打開「允許遠端開視窗與管理視窗」；換班接手會先請前任寫交接，最久等 10 分鐘。', 10),
  ('codex', 'Codex', '互動視窗', '沒有 Codex 帳號，無法實機測試；視窗若是「完全存取」模式，預設不轉外部來信（安全閘門）。', 20),
  ('gemini', 'Gemini', '背景工作者', '背景執行、沒有視窗；預設唯讀權限；一次處理一封信。', 30),
  ('grok-local', 'Grok', '本機背景工作者', '名單曾被誤當成雲端代理而選單全灰，已於 0.1.68 修好。 #234', 40),
  ('grok-cloud', 'Grok', '雲端代理', '還沒讓雲端代理遵守群組的依序回答（規劃中，#230）；同一個雲端環境有多位代理時，信目前先由主助理轉送（#241）。', 50),
  ('pi', 'pi', '互動視窗＋ASN 擴充', '要載入 ASN 擴充才能收信與切換模型。0.1.65～0.1.67 的 pi 收信其實沒生效，0.1.68 起修好；自己開的 pi 要經設定頁同意安裝擴充（方案 A，已隨 0.1.69 發佈）才會連上 ASN；打包漏列 control.mjs 的問題也已隨 0.1.68 修好（0.1.67 不受影響）。#242', 60)
insert into public.asn_site_matrix_cells (row_key, column_key, status, body, refs) values
  ('claude', 'open', 'ok', '從 ASN 開新的 Claude 視窗，電腦與手機都能下指令。', '{23}'::integer[]),
  ('claude', 'close', 'ok', '關閉視窗，對話紀錄保留，之後可「喚醒」接回同一段對話。', '{}'::integer[]),
  ('claude', 'adopt', 'ok', '同名視窗接手、穩定的夥伴身分（改名、換對話、換設備都延續）；自己開的視窗也能管理；另有「換班接手」。', '{82,107,109,153}'::integer[]),
  ('claude', 'model', 'ok', '直接在視窗內切換，不用重開；視窗內的外掛沒回應才退回重開。', '{82}'::integer[]),
  ('claude', 'group', 'ok', '已在群組中實際收發。', '{213}'::integer[]),
  ('claude', 'account', 'unv', '電腦版切換已發佈；手機遠端切換已隨 0.1.58 發佈，10/26 小良哥實際用過一次：家用機桌面其實切成功了，但回報給後端那段失敗，手機停在「等使用者按確認」。回報失敗重試與存檔補報（#301）已合併；「本人簽章的手機指令不用到桌面按確認」（#302）已隨 0.1.78 發佈（設定可關、每小時最多自動切 3 次、切換後電腦跳通知可還原），後端欄位已套用；還沒在家用機用手機實測一次。', '{51,227,300,301,302}'::integer[]),
  ('codex', 'open', 'tbc', '本機「開新夥伴」有 Codex 的啟動設定，但內建橋的 Codex 引擎註解寫「不支援遠端開 Codex 視窗」，兩邊矛盾，手機遠端開是否可行待查；開發機沒有 Codex 帳號，也沒有實機點開過。', '{}'::integer[]),
  ('codex', 'close', 'unv', '程式已隨 0.1.68 發佈，但選單尚未接線、仍反灰；未用真的 Codex 驗證。', '{238,235}'::integer[]),
  ('codex', 'adopt', 'na', '不需要接手：Codex 的名單、轉交、回覆本來就是對使用者自己開著的視窗做，收信不用接手。', '{}'::integer[]),
  ('codex', 'model', 'unv', '關閉後帶新模型重開同一段對話；程式已隨 0.1.68 發佈，選單仍反灰，未實機驗證。', '{238,235}'::integer[]),
  ('codex', 'group', 'tbc', '群組訊息與一般信件走同一條轉交，但查不到 Codex 在群組實際收發的紀錄。', '{}'::integer[]),
  ('codex', 'account', 'todo', '只顯示目前登入的帳號，切換尚未支援。', '{}'::integer[]),
  ('gemini', 'open', 'ok', '開新夥伴選 Gemini 後由內建橋消化請求、開出工作者。2026-10-25 在家用機實測：開出後約 7 秒內能回覆，ASN 重啟後會自動重建。', '{239}'::integer[]),
  ('gemini', 'close', 'unv', '「停止本次執行」已隨 0.1.68 發佈，只用模擬協議測過；重開或重啟 ASN 即恢復。', '{235}'::integer[]),
  ('gemini', 'adopt', 'todo', '不能接手自己開的 Gemini（規劃中）；有「換班接手」可換新一任。', '{}'::integer[]),
  ('gemini', 'model', 'todo', '尚未做：模型寫在設定檔、啟動時就定了；ACP 的切換模型還沒實測。', '{235}'::integer[]),
  ('gemini', 'group', 'ok', 'Gemini 夥伴已在群組中實際發言與收到點名。', '{}'::integer[]),
  ('gemini', 'account', 'todo', '尚未做。', '{}'::integer[]),
  ('grok-local', 'open', 'ok', '開新夥伴選 Grok 後由內建橋消化請求、開出工作者。2026-10-25 在家用機實測：約 17 秒內能回覆。0.1.70 起，Grok 執行檔不在系統路徑時也能在安裝位置找到（之前這種電腦永遠開不出來）。', '{239}'::integer[]),
  ('grok-local', 'close', 'unv', '「停止本次執行」已隨 0.1.68 發佈，只用模擬協議測過。', '{235}'::integer[]),
  ('grok-local', 'adopt', 'doing', '接手自己在終端機開的 Grok（載入同一段對話，要先關掉原終端機）已隨 0.1.67 發佈，但小良哥實測按「接手」失敗過一次（程式裡對得上「沒有設定 Grok 工作者」的錯誤）；0.1.68 的 #239 補了沒有設定檔時以開新夥伴開出的 Grok 工作者當底，但當時名冊裡沒有 Grok 工作者時仍會失敗；0.1.74 起（#269）沒有現成的 Grok 工作者也會用開新夥伴的 grok 設定建底，只用模擬工作者測過，等小良哥在手機重測確認。', '{239,269}'::integer[]),
  ('grok-local', 'model', 'todo', '尚未做：同 Gemini，模型寫在設定檔。', '{235}'::integer[]),
  ('grok-local', 'group', 'tbc', '走一般轉交；查不到本機 Grok 工作者在群組實際收發的紀錄。', '{}'::integer[]),
  ('grok-local', 'account', 'todo', '尚未做。', '{}'::integer[]),
  ('grok-cloud', 'open', 'ok', '用技能說明邀請安裝，一個雲端環境可住多位代理。', '{13}'::integer[]),
  ('grok-cloud', 'close', 'na', '在雲端執行，沒有電腦上的視窗。', '{}'::integer[]),
  ('grok-cloud', 'adopt', 'na', '沒有視窗可接手。', '{}'::integer[]),
  ('grok-cloud', 'model', 'na', 'ASN 不管理它的模型。', '{}'::integer[]),
  ('grok-cloud', 'group', 'ok', '能收群組訊息、在群組發言與讀歷史，已實際運作；收信是每 2 分鐘輪詢加門鈴。注意：舊版的雲端收信程式沒有群組輪詢，已經在跑的雲端代理要自己更新到新版才收得到群組訊息。', '{232,233}'::integer[]),
  ('grok-cloud', 'account', 'na', '雲端環境自己的帳號，ASN 不管理。', '{}'::integer[]),
  ('pi', 'open', 'tbc', '開新夥伴可直接開 pi（0.1.66）。但 0.1.65～0.1.67 的 pi 擴充沒有接上收信（入口沒呼叫 registerInbox），開出來的 pi 不會登記、收不到信；0.1.68 起修好，查不到從 ASN 開 pi 並收信的實機驗證紀錄。', '{237}'::integer[]),
  ('pi', 'close', 'todo', '尚未做，選單反灰，請直接在 pi 的終端機關掉。', '{235}'::integer[]),
  ('pi', 'adopt', 'doing', '自己開的 pi 沒裝擴充時只顯示。方案 A（在設定頁經你同意，替你的 pi 安裝 ASN 擴充，之後自己開的 pi 會登記到名單、能收信回信）已隨 0.1.69 發佈，尚未在真的視窗裡點過；已隨 0.1.79 預設改為開啟（第一次偵測到 pi 且還沒裝就自動安裝，設定頁可關閉並移除、關閉後不再裝回，#306）；0.1.78 以前自己按安裝會被誤判失敗（pi 把擴充存成相對路徑），0.1.79 修好，尚待負責人在桌面實測；方案 B（接手，用擴充重開同一段對話）進行中：第一階段（找出那個 pi 的對話檔的底層程式，沒有接線、使用者看不到變化）已合併，其餘還沒做。', '{240,243,246}'::integer[]),
  ('pi', 'model', 'unv', '擴充端、橋端與選單接線都已隨 0.1.68 發佈。只有載入 ASN 擴充的 pi 視窗能切換；擴充只在 pi 閒置時處理，忙碌會等到逾時並回「pi 沒有回應」。只在 pi 的 rpc 模式實測過，互動視窗與 ASN 選單內沒實機點過。', '{237,235}'::integer[]),
  ('pi', 'group', 'tbc', '群組訊息走一般轉交、由擴充注入。0.1.65～0.1.67 的 pi 收不到任何信（含群組），0.1.68 起修好，但查不到 pi 在群組實際收發的紀錄。', '{135,237}'::integer[]),
  ('pi', 'account', 'todo', '尚未做。', '{}'::integer[])
